title:
// ❌ 서버/클라이언트 결과 다를 때 발생
export default function Clock() {
  return <div>{new Date().toLocaleTimeString()}</div>
  // 서버 시간 ≠ 클라이언트 시간 → mismatch
}

// ✅ 클라이언트에서만 렌더링
'use client'
export default function Clock() {
  const [time, setTime] = useState<string | null>(null)
  useEffect(() => {
    setTime(new Date().toLocaleTimeString())
  }, [])
  if (!time) return null
  return <div>{time}</div>
}

