// Pages Router (Next.js 12) — 데이터와 UI 분리
export async function getServerSideProps() {
  const data = await db.query('...')
  return { props: { data } }  // props로 내려줘야 함
}
export default function Page({ data }) {
  return <div>{data}</div>
}

// App Router (Next.js 13+) — 컴포넌트 안에서 바로
export default async function Page() {
  const data = await db.query('...')  // 직접 접근
  return <div>{data}</div>
}

